   "rel_kind": "depends_on",
   "evidence": "Reporting still relies on Ledger"
  }
 ],
 "remove_relations": [],
 "entity_aliases": [
  {
   "name": "Reporting",
   "canonical": "reporting service",
   "evidence": "Reporting still relies on Ledger"
  },
  {
   "name": "Ledger",
   "canonical": "ledger service",
   "evidence": "Reporting still relies on Ledger"
  }
 ]
}

